SELECT r.reception_id, r.reception_no, r.patient_id, r.visit_type, r.department_id, r.doctor_id, r.reservation_id, r.scheduled_at, r.arrived_at, r.status, r.note, r.is_active, r.created_at, r.updated_at, i.admission_plan_at, i.ward_id, i.room_id FROM reception r JOIN reception_inpatient i ON r.reception_id = i.reception_id
r.visit_type = 'INPATIENT'
AND r.patient_name = #{searchValue}
AND r.status = #{searchValue}
AND i.ward_id = #{searchValue}
AND i.room_id = #{searchValue}
ORDER BY i.admission_plan_at ASC
